// Helper: Clean company name for query strings
function cleanCompanyName(name) {
  if (!name) return 'Company';
  return name.replace(/\s*\(PM\s*Internship\s*Scheme\)/gi, '')
             .replace(/\s*\(PM\s*Scheme\)/gi, '')
             .replace(/\s*\(TCS\)/gi, '')
             .replace(/\s*Innovation\s*Labs/gi, '')
             .replace(/\s*Development\s*Centre/gi, '')
             .replace(/\s*Technologies/gi, '')
             .replace(/\s*Corporation/gi, '')
             .replace(/\s*Software/gi, '')
             .replace(/\s*Services/gi, '')
             .replace(/\s*India/gi, '')
             .trim();
}

// Helper: Clean role title
function cleanRoleTitle(title) {
  if (!title) return 'Software Engineer';
  return title.replace(/\s*\(Track\s*#\d+\)/gi, '')
              .replace(/\s*\(Batch\s*#\d+\)/gi, '')
              .replace(/\s*\(₹[\d\.]+\s*LPA?\)/gi, '')
              .replace(/\s*\(2025–2026 Batch\)/gi, '')
              .replace(/\s*\(Freshers?\)/gi, '')
              .trim();
}

// Helper: Build exact, verified redirection URLs to the official job role portal
function buildDirectOpportunityLink(companyName, roleTitle) {
  const cleanComp = cleanCompanyName(companyName).toLowerCase();
  const cleanTitle = cleanRoleTitle(roleTitle);
  const qTitle = encodeURIComponent(cleanTitle);

  // PM Scheme official portal
  if (cleanComp.includes('pm scheme') || cleanComp.includes('pm internship') || companyName.toLowerCase().includes('pm scheme') || companyName.toLowerCase().includes('pm internship')) {
    return 'https://pminternship.mca.gov.in/';
  }

  // AICTE official portal
  if (cleanComp.includes('aicte') || companyName.toLowerCase().includes('aicte')) {
    return 'https://internship.aicte-india.org/';
  }

  // Google official career portal pre-filtered for exact role in India
  if (cleanComp.includes('google')) {
    return `https://www.google.com/about/careers/applications/jobs/results/?q=${qTitle}&location=India`;
  }

  // Microsoft official career portal pre-filtered for exact role in India
  if (cleanComp.includes('microsoft')) {
    return `https://careers.microsoft.com/v2/global/en/home.html#find-jobs?q=${qTitle}&p=India`;
  }

  // Amazon.jobs pre-filtered for exact role in India
  if (cleanComp.includes('amazon')) {
    return `https://www.amazon.jobs/en/search?base_query=${qTitle}&country=IND`;
  }

  // TCS official portals (NQT for campus drives, iBegin for specialized roles)
  if (cleanComp.includes('tcs') || cleanComp.includes('tata consultancy')) {
    if (roleTitle.toLowerCase().includes('ninja') || roleTitle.toLowerCase().includes('digital') || roleTitle.toLowerCase().includes('prime') || roleTitle.toLowerCase().includes('nqt')) {
      return 'https://www.tcs.com/careers/india/tcs-national-qualifier-test';
    }
    return `https://ibegin.tcs.com/iBegin/jobs/search?keyword=${qTitle}`;
  }

  // Infosys official career portal pre-filtered
  if (cleanComp.includes('infosys')) {
    return `https://career.infosys.com/joblist?keyword=${qTitle}&countrycode=IN`;
  }

  // ServiceNow official portal
  if (cleanComp.includes('servicenow')) {
    return `https://careers.servicenow.com/jobs?keywords=${qTitle}&location=India`;
  }

  // Cisco Systems official portal
  if (cleanComp.includes('cisco')) {
    return `https://jobs.cisco.com/jobs/SearchJobs/?keyword=${qTitle}&location=India`;
  }

  // Oracle official portal
  if (cleanComp.includes('oracle')) {
    return `https://careers.oracle.com/jobs/#en/sites/jobsearch/requisitions?keyword=${qTitle}&location=India`;
  }

  // Adobe Workday Careers
  if (cleanComp.includes('adobe')) {
    return `https://adobe.wd5.myworkdayjobs.com/en-US/external_experienced?q=${qTitle}&locations=9c85db5f553301fb4a45a3089d009087`;
  }

  // NVIDIA Workday Careers
  if (cleanComp.includes('nvidia')) {
    return `https://nvidia.wd5.myworkdayjobs.com/NVIDIAExternalCareerSite?q=${qTitle}&locations=c4f6faae728e1001e91122a6136d0000`;
  }

  // Salesforce Workday Careers
  if (cleanComp.includes('salesforce')) {
    return `https://salesforce.wd1.myworkdayjobs.com/External_Career_Site?q=${qTitle}&locations=987aa78939c301648a1dcf40be005b4b`;
  }

  // Goldman Sachs Campus Programs
  if (cleanComp.includes('goldman')) {
    return 'https://www.goldmansachs.com/careers/students/programs/india/new-analyst-programme.html';
  }

  // JPMorgan Chase Early Careers
  if (cleanComp.includes('jpmorgan') || cleanComp.includes('jp morgan') || cleanComp.includes('jpmc')) {
    return `https://careers.jpmorgan.com/global/en/students/programs?search=${qTitle}&tags=location__AsiaPacific__India`;
  }

  // Morgan Stanley Careers
  if (cleanComp.includes('morgan stanley')) {
    return 'https://morganstanley.tal.net/vx/lang-en-GB/mobile-0/appcentre-1/brand-2/xf-a7d0e461a8ef/candidate/jobboard/vacancy/1/adv/';
  }

  // Atlassian Careers
  if (cleanComp.includes('atlassian')) {
    return `https://www.atlassian.com/company/careers/all-jobs?location=India&search=${qTitle}`;
  }

  // Siemens Careers
  if (cleanComp.includes('siemens')) {
    return `https://jobs.siemens.com/careers?query=${qTitle}&location=India`;
  }

  // Wipro Careers
  if (cleanComp.includes('wipro')) {
    return `https://careers.wipro.com/global-india/jobs?keywords=${qTitle}&location=India`;
  }

  // Cognizant Careers
  if (cleanComp.includes('cognizant')) {
    return `https://careers.cognizant.com/global-en/jobs?keywords=${qTitle}&country=India`;
  }

  // Accenture Careers
  if (cleanComp.includes('accenture')) {
    return `https://www.accenture.com/in-en/careers/jobsearch?jk=${qTitle}&ct=India`;
  }

  // Capgemini Careers
  if (cleanComp.includes('capgemini')) {
    return `https://www.capgemini.com/in-en/careers/job-search/?keyword=${qTitle}`;
  }

  // IBM Careers
  if (cleanComp.includes('ibm')) {
    return `https://www.ibm.com/careers/in-en/search?field_keyword_08%5B0%5D=Entry%20Level&q=${qTitle}`;
  }

  // High-growth Tech & Unicorns
  if (cleanComp.includes('razorpay')) return 'https://razorpay.com/jobs/#open-positions';
  if (cleanComp.includes('phonepe')) return 'https://www.phonepe.com/careers/job-openings/';
  if (cleanComp.includes('swiggy')) return 'https://careers.swiggy.com/#/jobs';
  if (cleanComp.includes('zomato')) return 'https://www.zomato.com/careers';
  if (cleanComp.includes('cred')) return 'https://careers.cred.club/';
  if (cleanComp.includes('groww')) return 'https://groww.in/careers';
  if (cleanComp.includes('zerodha')) return 'https://zerodha.com/careers/';
  if (cleanComp.includes('postman')) return 'https://www.postman.com/careers/';
  if (cleanComp.includes('meesho')) return 'https://www.meesho.io/jobs';
  if (cleanComp.includes('paytm')) return 'https://paytm.com/careers/';
  if (cleanComp.includes('larsen') || cleanComp.includes('l&t')) return 'https://www.larsentoubro.com/corporate/careers/';
  if (cleanComp.includes('bosch')) return 'https://www.bosch.in/careers/';
  if (cleanComp.includes('tata motors')) return 'https://www.tatamotors.com/careers/';

  // High-precision LinkedIn Jobs fallback
  return `https://www.linkedin.com/jobs/search/?keywords=${encodeURIComponent(cleanCompanyName(companyName) + ' ' + cleanTitle)}&location=India&f_TPR=r2592000`;
}

// Build verified LinkedIn search link pre-filled with company and role
function buildLinkedInOpportunityLink(companyName, roleTitle) {
  const cleanComp = cleanCompanyName(companyName);
  const cleanTitle = cleanRoleTitle(roleTitle);
  return `https://www.linkedin.com/jobs/search/?keywords=${encodeURIComponent(cleanComp + ' ' + cleanTitle)}&location=India&f_TPR=r2592000`;
}

