// Helper: Map MongoDB Drive document to full Opportunity object matching ALL_JOBS schema
function mapDriveToOpportunity(d) {
  if (!d) return null;
  const comp = d.company && typeof d.company === 'object' ? d.company : null;
  const compName = comp?.name || d.company_name || d.companyName || 'Verified Corporate Partner';
  const jobType = d.jobType || d.job_type || 'Full-Time';
  const oppType = d.opportunityType || (jobType.toLowerCase().includes('intern') ? 'Internship' : (jobType.toLowerCase().includes('skill') ? 'Skill' : 'Placement'));

  let normalizedJobType = 'Full-time';
  if (oppType === 'Internship' || jobType.toLowerCase().includes('intern')) {
    normalizedJobType = 'Internship';
  } else if (oppType === 'Skill' || jobType.toLowerCase().includes('skill')) {
    normalizedJobType = 'Skill';
  }

  const category = d.category || (normalizedJobType === 'Internship' ? 'Internships' : (normalizedJobType === 'Skill' ? 'Skill Up' : 'Software Engineering'));
  const idStr = `drive-${d._id || d.id}`;
  const ctcNum = Number(d.ctc || d.package || 0);
  const salaryStr = normalizedJobType === 'Internship'
    ? (ctcNum > 0 ? (ctcNum < 100 ? `₹${ctcNum},000/mo` : `₹${ctcNum} LPA Stipend`) : 'Competitive Stipend')
    : normalizedJobType === 'Skill'
      ? 'Free Certification & Placement Assistance'
      : (ctcNum > 0 ? `₹${ctcNum} LPA` : 'Competitive CTC');

  const tags = Array.isArray(d.skills) && d.skills.length > 0 ? [...d.skills] : ['Campus Placement', 'Engineering', 'Verified'];
  if (d.branches && d.branches.length > 0) {
    tags.push(...d.branches.slice(0, 2));
  }

  const deadlineStr = d.deadline ? (d.deadline instanceof Date ? d.deadline.toISOString().split('T')[0] : String(d.deadline).split('T')[0]) : 'Rolling';

  return {
    id: idStr,
    mongo_id: (d._id || d.id).toString(),
    drive_id: (d._id || d.id).toString(),
    is_campus_drive: true,
    is_verified: true,
    title: d.title,
    company: compName,
    company_name: compName,
    company_id: comp?._id || comp?.id || d.company_id || 1,
    company_email: comp?.email || d.company_email || 'hr@technova.com',
    logo: comp?.logo || '/static/images/companies/default.svg',
    location: d.location || 'Pan-India / Hybrid',
    work_mode: 'Hybrid',
    job_type: normalizedJobType,
    category: category,
    salary: salaryStr,
    experience: `Eligible CGPA: ${d.minCgpa ?? d.min_cgpa ?? 6.0}+`,
    min_cgpa: d.minCgpa ?? d.min_cgpa ?? 6.0,
    tags: Array.from(new Set(tags)),
    source: `${compName} (Verified Placement Partner)`,
    url: `/student/opportunities`,
    application_url: `/student/opportunities`,
    direct_job_url: `/student/opportunities`,
    posted_at: d.createdAt ? (d.createdAt instanceof Date ? d.createdAt.toISOString().split('T')[0] : String(d.createdAt).split('T')[0]) : new Date().toISOString().split('T')[0],
    deadline: deadlineStr,
    openings: d.openings || 1,
    description: d.description || `Official campus placement and career opportunity with ${compName}. Open to eligible university students.`,
    responsibilities: [
      `Participate actively in ${compName}'s engineering and operations workflow.`,
      'Collaborate across cross-functional teams to build and ship production software.',
      'Maintain adherence to industry standards, code reviews, and testing protocols.'
    ],
    requirements: [
      `Minimum CGPA of ${d.minCgpa ?? d.min_cgpa ?? 6.0} with max ${d.maxBacklogs ?? d.max_backlogs ?? 0} active backlogs.`,
      `Open to eligible branches: ${(d.branches && d.branches.length > 0) ? d.branches.join(', ') : 'All Engineering / Tech streams'}.`,
      `Required skill proficiencies: ${(d.skills && d.skills.length > 0) ? d.skills.join(', ') : 'Software fundamentals, problem solving'}.`
    ],
    rounds: [
      'Round 1: Profile & Resume Screening',
      'Round 2: Online Technical Assessment',
      'Round 3: Technical Interview',
      'Round 4: Selection & Offer Letter Release'
    ]
  };
}

// Helper: Query active opportunities posted by verified companies
async function fetchVerifiedCompanyOpportunities() {
  const verifiedList = [];
  const seenIds = new Set();

  if (mongoose.connection && mongoose.connection.readyState === 1 && Drive) {
    try {
      const drives = await Drive.find({ status: 'active' }).populate('company').sort({ createdAt: -1 }).lean();
      for (const d of drives) {
        if (d.company && d.company.approved === true) {
          const opp = mapDriveToOpportunity(d);
          if (opp) {
            verifiedList.push(opp);
            seenIds.add(opp.mongo_id);
          }
        }
      }
    } catch (err) {
      console.warn('[JobController Fetch Verified Drives Error]:', err.message);
    }
  }

  if (recruiterStore && Array.isArray(recruiterStore.drives)) {
    for (const d of recruiterStore.drives) {
      const dId = String(d._id || d.id);
      if (!seenIds.has(dId) && d.status === 'active') {
        let isApproved = d.company?.approved === true || d.companyApproved === true;
        if (!isApproved && d.company_email && recruiterStore.companies && recruiterStore.companies.has(d.company_email)) {
          isApproved = recruiterStore.companies.get(d.company_email)?.approved === true;
        }
        if (isApproved) {
          const opp = mapDriveToOpportunity(d);
          if (opp) verifiedList.push(opp);
        }
      }
    }
  }

  return verifiedList;
}

// GET /api/jobs
exports.getJobs = async (req, res) => {
  const {
    job_type,
    category,
    q,
    location,
    work_mode,
    source,
    page = 1,
    limit = 12
  } = req.query;

  // Prepend verified company opportunities to ALL_JOBS so they appear at top of listings
  const verifiedOpportunities = await fetchVerifiedCompanyOpportunities();
  let baseFiltered = [...verifiedOpportunities, ...ALL_JOBS];

  // 1. Text Search & Acronym expansion
  if (q) {
    const queryStr = q.toLowerCase().trim();
    const isTcs = queryStr === 'tcs' || queryStr.includes('tcs') || queryStr.includes('tata consultancy');
    const isLt = queryStr === 'l&t' || queryStr === 'lnt' || queryStr.includes('larsen');
    const isPmi = queryStr.includes('pm scheme') || queryStr.includes('pm internship') || queryStr === 'pm' || queryStr === 'pmi';
    const isGoogle = queryStr.includes('google');
    const isMicrosoft = queryStr.includes('microsoft') || queryStr.includes('msft');
    const isAmazon = queryStr.includes('amazon') || queryStr.includes('aws');
    const isInfosys = queryStr.includes('infosys') || queryStr.includes('infy');
    const isAicte = queryStr.includes('aicte');

    baseFiltered = baseFiltered.filter(j => {
      const compStr = (j.company || j.company_name || '').toLowerCase();
      const titleStr = (j.title || '').toLowerCase();
      const locStr = (j.location || '').toLowerCase();
      const tagMatch = j.tags && j.tags.some(t => t.toLowerCase().includes(queryStr));
      const sourceStr = (j.source || '').toLowerCase();

      // Specific company matches
      if (isGoogle && (compStr.includes('google') || titleStr.includes('google') || sourceStr.includes('google'))) return true;
      if (isMicrosoft && (compStr.includes('microsoft') || titleStr.includes('microsoft') || sourceStr.includes('microsoft'))) return true;
      if (isAmazon && (compStr.includes('amazon') || titleStr.includes('amazon') || sourceStr.includes('amazon'))) return true;
      if (isTcs && (compStr.includes('tata consultancy') || compStr.includes('tcs') || titleStr.includes('tcs') || (j.tags && j.tags.includes('TCS')))) return true;
      if (isInfosys && (compStr.includes('infosys') || titleStr.includes('infosys') || sourceStr.includes('infosys'))) return true;
      if (isAicte && (compStr.includes('aicte') || titleStr.includes('aicte') || sourceStr.includes('aicte'))) return true;
      if (isPmi && (j.job_type === 'PM Internship Scheme' || titleStr.includes('pm scheme') || compStr.includes('pm scheme') || compStr.includes('pm internship'))) return true;
      if (isLt && (compStr.includes('larsen') || compStr.includes('l&t') || compStr.includes('ltts'))) return true;

      // General term matches
      if (titleStr.includes(queryStr) || compStr.includes(queryStr) || locStr.includes(queryStr) || tagMatch || sourceStr.includes(queryStr)) {
        return true;
      }

      return false;
    });
  }

  if (work_mode) {
    baseFiltered = baseFiltered.filter(j => j.work_mode.toLowerCase() === work_mode.toLowerCase());
  }

  if (category) {
    baseFiltered = baseFiltered.filter(j => j.category.toLowerCase() === category.toLowerCase());
  }

  if (source) {
    baseFiltered = baseFiltered.filter(j => j.source.toLowerCase().includes(source.toLowerCase()));
  }

  // Dynamic counts for each category tab matching the current query
  const totalAllCount = baseFiltered.length;
  const totalPlacementsCount = baseFiltered.filter(j => j.job_type === 'Full-time').length;
  const totalInternshipsCount = baseFiltered.filter(j => j.job_type === 'Internship' || j.job_type === 'PM Internship Scheme').length;
  const totalSkillsCount = baseFiltered.filter(j => j.job_type === 'Skill' || j.category === 'Skill Up' || j.category === 'Skills' || (j.tags && j.tags.includes('Skill'))).length;

  // 2. Apply Job Type Filter
  let filtered = [...baseFiltered];
  if (job_type) {
    const jt = job_type.toLowerCase();
    if (jt === 'full-time' || jt === 'fulltime' || jt === 'placements' || jt === 'campus placement drive') {
      filtered = filtered.filter(j => j.job_type === 'Full-time');
    } else if (jt === 'internship' || jt === 'internships' || jt === 'pm internship scheme' || jt === 'pm scheme') {
      filtered = filtered.filter(j => j.job_type === 'Internship' || j.job_type === 'PM Internship Scheme');
    } else if (jt === 'skill' || jt === 'skills' || jt === 'skill up') {
      filtered = filtered.filter(j => j.job_type === 'Skill' || j.category === 'Skill Up' || j.category === 'Skills' || (j.tags && j.tags.includes('Skill')));
    } else {
      filtered = filtered.filter(j => j.job_type.toLowerCase() === jt || j.category.toLowerCase().includes(jt));
    }
  }

  const totalMatching = filtered.length;
  const perPage = Math.min(100, Math.max(1, parseInt(limit, 10) || 12));
  const totalPages = Math.max(1, Math.ceil(totalMatching / perPage));
  const pageNum = Math.min(totalPages, Math.max(1, parseInt(page, 10) || 1));
  const startIndex = (pageNum - 1) * perPage;
  const paginatedJobs = filtered.slice(startIndex, startIndex + perPage);

  const relevantFeaturedCompanies = !job_type
    ? FEATURED_MNC_COMPANIES
    : (job_type.toLowerCase().includes('intern') || job_type.toLowerCase().includes('pm'))
      ? FEATURED_MNC_COMPANIES.filter(c => c.category === 'Internship' || c.category === 'both')
      : FEATURED_MNC_COMPANIES.filter(c => c.category === 'Full-time' || c.category === 'both');

  return res.status(200).json({
    success: true,
    total_jobs: totalMatching,
    total_all_count: totalAllCount,
    total_placements_count: totalPlacementsCount,
    total_internships_count: totalInternshipsCount,
    total_skills_count: totalSkillsCount,
    page: pageNum,
    limit: perPage,
    total_pages: totalPages,
    featured_companies: relevantFeaturedCompanies,
    data: paginatedJobs
  });
};

